const KEY='garage-vivant-profile-layout';
let preferences={order:[],hidden:[],wide:[],columns:{}};try{preferences={...preferences,...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{}
export function profileMarkup(html){const template=document.createElement('template');template.innerHTML=html;const nodes=[...template.content.children];const modules=[];nodes.forEach((node,index)=>{if(!['SECTION','DETAILS'].includes(node.tagName)&&node.id!=='rapin-pool')return;const id=node.id||node.dataset.stable||node.querySelector('[id]')?.id||`section-${index}`;node.dataset.key='module-'+id;node.dataset.module=id;node.classList.add('profile-module');if(preferences.wide.includes(id))node.classList.add('module-wide');else if(preferences.columns[id])node.classList.add('module-'+preferences.columns[id]);const toolbar=document.createElement('div');toolbar.className='module-toolbar';toolbar.innerHTML=`<button data-module="${id}" data-module-action="up" aria-label="Monter le module">↑</button><button data-module="${id}" data-module-action="down" aria-label="Descendre le module">↓</button><button data-module="${id}" data-module-action="column" title="Changer de colonne : automatique, gauche, droite">⇥</button><button data-module="${id}" data-module-action="wide" title="Largeur du module">↔</button><button data-module="${id}" data-module-action="hide">${preferences.hidden.includes(id)?'Afficher':'Masquer'}</button>`;if(node.tagName==='DETAILS')node.querySelector('summary')?.after(toolbar);else node.prepend(toolbar);modules.push({id,node,index});});const main=document.createElement('div');main.className='profile-modules';main.dataset.key='profile-modules';const hidden=document.createElement('details');hidden.dataset.key='hidden-modules';hidden.className='hidden-modules';hidden.innerHTML='<summary>Modules masqués · accessibles ici</summary>';modules.sort((a,b)=>{const index=id=>preferences.order.includes(id)?preferences.order.indexOf(id):1000+modules.find(x=>x.id===id).index;return index(a.id)-index(b.id);});for(const {id,node} of modules)(preferences.hidden.includes(id)?hidden:main).append(node);template.content.append(main,hidden);const reset=document.createElement('button');reset.dataset.resetLayout='';reset.textContent='Rétablir la disposition';template.content.append(reset);return template.innerHTML;}
export function changeModule(id,action){const nodes=[...document.querySelectorAll('#profile [data-module]')].filter(x=>x.classList.contains('profile-module')),all=nodes.map(n=>n.dataset.module);preferences.order=[...new Set([...preferences.order,...all])];const i=preferences.order.indexOf(id);if(action==='up'&&i>0)[preferences.order[i-1],preferences.order[i]]=[preferences.order[i],preferences.order[i-1]];if(action==='down'&&i<preferences.order.length-1)[preferences.order[i+1],preferences.order[i]]=[preferences.order[i],preferences.order[i+1]];if(action==='column')preferences.columns[id]=({left:'right',right:null})[preferences.columns[id]]||(!preferences.columns[id]?'left':null);if(action==='hide'||action==='wide'){const key=action==='hide'?'hidden':'wide';preferences[key]=preferences[key].includes(id)?preferences[key].filter(x=>x!==id):[...preferences[key],id];}try{localStorage.setItem(KEY,JSON.stringify(preferences));}catch{}}
export function resetLayout(){preferences={order:[],hidden:[],wide:[],columns:{}};try{localStorage.removeItem(KEY);}catch{}}
